<?php
require_once __DIR__.'/includes/functions.php';
$q=trim($_GET['q']??''); $level=(int)($_GET['level']??0); $semester=$_GET['semester']??''; $session=trim($_GET['session']??'');
$results=[];
$searchKey=preg_replace('/[^a-z0-9]+/i','',strtolower($q));
if($q!=='' || $level || $semester!=='' || $session!==''){
 $sql="SELECT r.id,r.public_token,r.tracking_no,r.session_name,r.current_since,c.course_code,c.course_title,c.level,c.semester,GROUP_CONCAT(l.full_name ORDER BY l.id SEPARATOR ', ') lecturer_name,s.stage_name,o.office_name FROM result_records r JOIN courses c ON c.id=r.course_id JOIN course_lecturers cl ON cl.course_id=c.id JOIN lecturers l ON l.id=cl.lecturer_id JOIN status_stages s ON s.id=r.current_stage_id LEFT JOIN offices o ON o.id=r.current_office_id WHERE 1"; $p=[];
 if($searchKey!==''){ $sql.=" AND (LOWER(REPLACE(REPLACE(REPLACE(REPLACE(c.course_code,' ',''),'-',''),'.',''),'_','')) LIKE ? OR LOWER(REPLACE(REPLACE(REPLACE(REPLACE(c.course_title,' ',''),'-',''),'.',''),'_','')) LIKE ? OR LOWER(REPLACE(REPLACE(REPLACE(REPLACE(l.full_name,' ',''),'-',''),'.',''),'_','')) LIKE ?)"; $p=["%$searchKey%","%$searchKey%","%$searchKey%"]; }
 if($level){$sql.=' AND c.level=?';$p[]=$level;} if($semester!==''){$sql.=' AND c.semester=?';$p[]=$semester;} if($session!==''){$sql.=' AND r.session_name=?';$p[]=$session;}
 $sql.=' GROUP BY r.id ORDER BY r.updated_at DESC'; $st=db()->prepare($sql);$st->execute($p);$results=$st->fetchAll();
}
function public_stage_count($stage){return 0;}
